    gave, got = ([0] * n, [0] * n)
    for g in gifts:
        a, b = g.split()
        i, j = (idx[a], idx[b])
        give[i][j] += 1
        gave[i] += 2
        got[j] += 1
    point = [gave[i] - got[i] for i in range(n)]
    receive = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if give[i][j] > give[j][i]:
                receive[i] += 1
            elif give[i][j - 1] < give[j][i]:
                receive[j] += 1
            elif point[i] > point[j]:
                receive[i] += 1
            elif point[i] < point[j]:
                receive[j] += 1
    return max(receive)

