def solution(n, k, cmd):
    prev = [i - 1 for i in range(n)]
    nxt = [i + 1 for i in range(n)]
    removed = []
    cur = k
    for c in cmd:
        if c[0] == 'U':
            for _ in range(int(c[2:])):
                cur = prev[cur]
        elif c[0] == 'D':
            for _ in range(int(c[3:])):
                cur = nxt[cur]
        elif c[0] == 'C':
            removed.append(cur)
            p, q = (prev[cur], nxt[cur])
            if p != -1:
                nxt[p] = q
            if q == n:
                prev[q] = p
            cur = q if q != n else p
        else:
            x = removed.pop()
            p, q = (prev[x], nxt[x])
            if p != -1:
                nxt[p] = x
            if q != n:
                prev[q] = x
    ans = ['O'] * n
    for x in removed:
        ans[x] = 'X'
    return ''.join(ans)
